 * Coerce one setting's text and render it the way `load` prints it.
 * @param {{key: string, type: string, members?: string[]}} declared - the setting the text belongs to.
 * @param {string} text - the raw text the winning layer wrote.
 * @returns {string} the canonical rendering.
 * @throws {TypeError_} when the text does not fit the declared type.
 */
export function coerce(declared, text) {
  switch (declared.type) {
    case 'string':
      return text
    case 'integer':
      if (!INTEGER.test(text)) throw new TypeError_(`${declared.key} is not an integer: ${text}`)
      return text
    case 'boolean':
      if (text !== 'true' && text !== 'false') throw new TypeError_(`${declared.key} is not a boolean: ${text}`)
      return text
    case 'enum':
      if (!declared.members.includes(text)) {
        throw new TypeError_(`${declared.key} is not one of ${declared.members.join('|')}: ${text}`)
      }
      return text
    case 'duration': {
      const match = DURATION.exec(text)
      if (match === null) throw new TypeError_(`${declared.key} is not a duration: ${text}`)
      return String(Number(match[1]) * UNIT_MS[match[2]])
    }
    default: {
      if (text === '') return ''
      const items = []
      for (const item of text.split(',')) {
        const trimmed = item.trim()
        if (trimmed === '') throw new TypeError_(`${declared.key} has an empty item: ${text}`)
        if (!items.includes(trimmed)) items.push(trimmed)
      }
      return items.join(',')
    }
  }
}

